/*@part base-2*/
const GR_ZH4A=[
["Even with 连…都…","连 + A + 都/也 + verb phrase","连 (lián) … 都 (dōu) means “even”. Put the extreme example between 连 and 都. If the extreme example is true, then the easier examples are also true.",[["连","lián","even"],["孩子","háizi","child"],["都","dōu","all"],["懂","dǒng","to understand"],["。","",""]],"Even a child understands."],
["The more … the more with 越…越…","越 + A + 越 + B","越 (yuè) … 越 (yuè) means “the more … the more”. Put a verb or an adjective after each 越. The second state grows as the first one grows. This is not the same as 越来越, which has no second part.",[["雨","yǔ","rain"],["越","yuè","the more"],["下","xià","to fall"],["越","yuè","the more"],["大","dà","big"],["。","",""]],"The more it rains, the heavier it gets."],
["Would rather … than with 宁可…也不…","宁可 + A，也 + 不 + B","宁可 (nìngkě) … 也不 (yě bù) … means “would rather A than B”. A is the choice that the speaker accepts. B is the choice that the speaker refuses.",[["我","wǒ","I"],["宁可","nìngkě","would rather"],["走路","zǒulù","to walk"],["，","",""],["也","yě","also"],["不","bú","not"],["坐","zuò","to travel by"],["车","chē","car"],["。","",""]],"I would rather walk than take a car."],
["Even though with 尽管…但是…","尽管 + A，但是 + B","尽管 (jǐnguǎn) means “even though”. It is like 虽然, but the fact in A is stronger. Part B often has 但是 or 还是 and shows what is still true.",[["尽管","jǐnguǎn","even though"],["下雨","xià yǔ","to rain"],["，","",""],["但是","dànshì","but"],["他们","tāmen","they"],["还是","háishi","still"],["去","qù","go"],["了","le","(completed)"],["。","",""]],"Even though it rained, they still went."],
["For someone with 对…来说","对 + person + 来说，comment","对 (duì) … 来说 (láishuō) means “for” or “as far as someone is concerned”. After it, give a comment about how it is for that person.",[["对","duì","to"],["我","wǒ","I"],["来说","láishuō","as far as"],["，","",""],["中文","Zhōngwén","Chinese"],["很","hěn","very"],["难","nán","difficult"],["。","",""]],"For me, Chinese is difficult."],
["Unexpected result with 倒","A 不 + adjective，倒 + adjective","倒 (dào) comes before an adjective or verb. It shows that the fact is the opposite of what you could expect from the first part of the sentence.",[["这","zhè","this"],["个","ge","(measure word)"],["包","bāo","bag"],["不","bú","not"],["大","dà","big"],["，","",""],["倒","dào","on the contrary"],["很","hěn","very"],["重","zhòng","heavy"],["。","",""]],"This bag is not big, but it is quite heavy."],
["Surprise with 竟然","Subject + 竟然 + verb phrase","竟然 (jìngrán) means “unexpectedly”. It goes before the verb. The speaker did not expect this fact.",[["他","tā","he"],["竟然","jìngrán","unexpectedly"],["没有","méiyǒu","do not have"],["来","lái","come"],["。","",""]],"He unexpectedly did not come."],
["Even if with 即使…也…","即使 + A，也 + B","即使 (jíshǐ) means “even if”. A is a situation that may or may not happen. B is what stays the same in that situation. 也 (yě) must come before the verb in B.",[["即使","jíshǐ","even if"],["下雨","xià yǔ","to rain"],["，","",""],["我","wǒ","I"],["也","yě","also"],["去","qù","go"],["。","",""]],"Even if it rains, I will still go."],
["As long as with 只要…就…","只要 + A，就 + B","只要 (zhǐyào) means “as long as”. A is a condition that is enough. 就 (jiù) in B gives the result of the condition.",[["只要","zhǐyào","as long as"],["你","nǐ","you"],["想","xiǎng","want to"],["，","",""],["就","jiù","then"],["可以","kěyǐ","may"],["。","",""]],"As long as you want to, you can."],
["Only if with 只有…才…","只有 + A，才 + B","只有 (zhǐyǒu) means “only if”. A is the one condition that is needed. 才 (cái) in B shows that the result happens only under that condition.",[["只有","zhǐyǒu","only if"],["多","duō","many"],["练习","liànxí","to practise"],["，","",""],["才","cái","only then"],["能","néng","can"],["说","shuō","say"],["好","hǎo","good"],["。","",""]],"Only by practising more can you speak well."]
];
